// And groups predicates with the AND operator between them.
func And(predicates ...predicate.NativeConsumerSession) predicate.NativeConsumerSession {
	return predicate.NativeConsumerSession(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.NativeConsumerSession) predicate.NativeConsumerSession {
	return predicate.NativeConsumerSession(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.NativeConsumerSession) predicate.NativeConsumerSession {
	return predicate.NativeConsumerSession(sql.NotPredicates(p))
}
